acc_car:
#ifdef GL_FRAGMENT_PRECISION_HIGH
precision highp float;
#else
precision mediump float;
#endif
varying vec2 v_uv;
uniform vec2 u_size;
uniform vec3 u_body;
uniform vec2 u_dim;
uniform vec4 u_lamp;
float box(vec2 q, vec2 c, vec2 b, float r) {
vec2 e = abs(q - c) - b + vec2(r);
return length(max(e, 0.0)) + min(max(e.x, e.y), 0.0) - r;
}
void main() {
float a = u_size.x / u_size.y;
vec2 q = vec2((v_uv.x - 0.5) * a, v_uv.y);
float aa = 1.2 / u_size.y;
float ax = abs(q.x);
vec2 s = (q - vec2(0.0, 0.94)) / vec2(0.82, 0.075);
float shadow = (1.0 - smoothstep(0.4, 1.0, dot(s, s))) * 0.55;
vec4 c = vec4(0.0, 0.0, 0.0, shadow);
float ty = box(vec2(ax, q.y), vec2(0.53, 0.86), vec2(0.105, 0.095), 0.03);
float kt = 1.0 - smoothstep(-aa, aa, ty);
c = mix(c, vec4(vec3(0.07), 1.0), kt);
float f = clamp((q.y - 0.17) / 0.30, 0.0, 1.0);
float cab = box(vec2(ax * 0.62 / mix(0.43, 0.62, f), q.y), vec2(0.0, 0.32), vec2(0.62, 0.15), 0.07);
float body = box(q, vec2(0.0, 0.63), vec2(0.70, 0.20), 0.11);
float mir = box(vec2(ax, q.y), vec2(0.70, 0.40), vec2(0.07, 0.035), 0.03);
float sil = min(min(cab, body), mir);
float k = 1.0 - smoothstep(-aa, aa, sil);
float lit = 0.62 + 0.38 * (1.0 - q.y);
lit *= 1.0 - 0.38 * smoothstep(0.40, 0.72, ax);
lit += 0.30 * (1.0 - smoothstep(0.0, 0.025, abs(q.y - 0.455))) * (1.0 - smoothstep(0.50, 0.66, ax));
lit *= 0.70 + 0.30 * smoothstep(-0.06, -0.005, -sil);
vec3 col = u_body * lit;
float win = box(vec2(ax * 0.55 / mix(0.37, 0.55, f), q.y), vec2(0.0, 0.335), vec2(0.55, 0.105), 0.045);
float kw = 1.0 - smoothstep(-aa, aa, win);
vec3 glass = vec3(0.05, 0.06, 0.08) + vec3(0.16, 0.18, 0.21) * (1.0 - smoothstep(0.0, 0.08, abs(q.x * 0.6 + q.y - 0.42))) + 0.08 * (1.0 - f);
col = mix(col, glass, kw);
float lamp = box(q, vec2(0.0, 0.53), vec2(0.66, 0.035), 0.02);
float kl = 1.0 - smoothstep(-aa, aa, lamp);
col = mix(col, vec3(0.10, 0.10, 0.11) + 0.18 * u_body * (1.0 - smoothstep(0.0, 0.66, ax)), kl);
float dl = length(vec2(ax - 0.52, q.y - 0.53));
col = mix(col, u_lamp.rgb, u_lamp.w * max(1.0 - smoothstep(0.06, 0.06 + aa, dl), kl * (1.0 - smoothstep(0.0, 0.3, dl))));
float plate = box(q, vec2(0.0, 0.69), vec2(0.15, 0.045), 0.01);
col = mix(col, u_body * 0.35, 1.0 - smoothstep(-aa, aa, plate));
float diff = box(q, vec2(0.0, 0.80), vec2(0.52, 0.025), 0.02);
col = mix(col, vec3(0.06), 1.0 - smoothstep(-aa, aa, diff));
c = mix(c, vec4(col, 1.0), k);
gl_FragColor = vec4(c.rgb * (1.0 - 0.65 * u_dim.x), c.a);
}

acc_lane:
#ifdef GL_FRAGMENT_PRECISION_HIGH
precision highp float;
#else
precision mediump float;
#endif
varying vec2 v_uv;
uniform vec2 u_size;
uniform vec4 u_view;
uniform vec4 u_ln[4];
uniform vec4 u_lp[4];
uniform vec4 u_ego;
uniform vec3 u_line;
uniform vec3 u_ground;
uniform vec4 u_gap;
uniform vec3 u_gapc;
uniform vec4 u_beam;
uniform vec3 u_beamc;
void main() {
vec2 p = v_uv * u_size;
float hy = u_view.x * u_size.y;
float t = (p.y - hy) / (u_size.y - hy);
vec4 c = vec4(0.0);
if (t > 0.0) {
float z = (1.0 / t - 1.0) / u_view.z;
float xm = z * u_view.w;
float k = u_view.y * t;
float ym = (0.5 * u_size.x - p.x) / k;
float fade = 1.0 - smoothstep(0.55, 1.0, z);
float ce = u_ego.x + xm * (u_ego.y + 0.5 * u_ego.z * xm);
float aX = abs(ym - ce) / u_ego.w;
float edge = smoothstep(0.0, 48.0, min(p.x, u_size.x - p.x)) * smoothstep(0.0, 16.0, u_size.y - p.y);
float ground = (0.30 + 0.70 * clamp(1.0 - z, 0.0, 1.0)) * (1.0 - smoothstep(2.6, 5.5, aX)) * edge;
c = vec4(u_ground, ground * fade);
if (u_beam.y > 0.0) {
float xf = xm - u_beam.w;
float yb = abs(ym - u_beam.z);
float lowW = 1.0 + 5.2 * (1.0 - exp(-xf / 8.0));
float low = 0.62 * (1.0 - smoothstep(43.2, 60.0, xf)) * (0.55 + 0.45 * exp(-xf / 25.0));
float reach = 60.0 + 160.0 * u_beam.x;
float highW = 0.8 + 3.4 * (1.0 - exp(-xf / 40.0));
float high = 0.5 * sqrt(u_beam.x) * (1.0 - smoothstep(reach * 0.55, reach, xf)) * (0.55 + 0.45 * exp(-xf / 90.0));
float lk = step(0.5, xf) * min(1.0, low * (1.0 - smoothstep(0.6 * lowW, lowW, yb)) + high * (1.0 - smoothstep(0.45 * highW, highW, yb))) * fade * u_beam.y;
c.rgb = mix(c.rgb, u_beamc, lk);
c.a = max(c.a, lk);
}
if (u_gap.x > 0.0 && z < u_gap.x) {
float g = u_gap.z * (1.0 - smoothstep(0.72, 0.92, aX)) * smoothstep(0.0, 0.04, u_gap.x - z);
c.rgb = mix(c.rgb, u_gapc, g);
c.a = max(c.a, g * fade);
for (int i = 0; i < 2; i++) {
float tc = 1.0 / (1.0 + u_gap.x * (0.45 + 0.22 * float(i)) * u_view.z);
float yc = hy + (u_size.y - hy) * tc;
float d = (p.y - yc - aX * u_ego.w * u_view.y * tc * 0.28) / (0.1 * u_view.y * tc * 0.9 + 0.8);
float on = (1.0 - smoothstep(0.6, 1.0, abs(d))) * (1.0 - smoothstep(0.42, 0.52, aX)) * step(float(i) + 0.5, u_gap.y);
c.rgb = mix(c.rgb, u_gapc, on);
c.a = max(c.a, on * fade);
}
}
for (int i = 0; i < 4; i++) {
vec4 l = u_ln[i];
vec4 q = u_lp[i];
if (l.w > 0.5 && xm < q.x) {
float d = abs(ym - (l.x + xm * (l.y + 0.5 * l.z * xm))) * k;
float lw = max(1.2, q.z * k) * (1.0 - 0.5 * q.w);
if (l.w > 2.5 && l.w < 3.5) d = abs(d - 1.4 * lw * (1.0 - q.w));
float on = 1.0 - smoothstep(lw * 0.5 - 0.7, lw * 0.5 + 0.7, d);
float glow = (1.0 - smoothstep(0.0, lw * 2.5 + 2.0, d)) * 0.25 * (1.0 - q.w);
float dash = (l.w > 1.5 && l.w < 2.5) ? step(fract(xm / 12.0), 0.5) : 1.0;
dash = mix(dash, step(fract(xm / 5.0), 0.4), q.w);
float kk = max(on, glow) * dash * fade * q.y * (1.0 - smoothstep(q.x - 8.0 - 30.0 * q.w, q.x, xm));
c.rgb = mix(c.rgb, mix(l.w > 3.5 ? u_line * 0.5 + vec3(0.14) : u_line, u_line, q.w), kk);
c.a = max(c.a, kk);
}
}
}
gl_FragColor = vec4(c.rgb * (1.0 - 0.65 * u_gap.w), c.a);
}

acc_obj:
#ifdef GL_FRAGMENT_PRECISION_HIGH
precision highp float;
#else
precision mediump float;
#endif
varying vec2 v_uv;
uniform vec2 u_size;
uniform vec4 u_ob[16];
uniform vec4 u_oc[16];
uniform vec3 u_fill;
uniform vec2 u_dim;
float box(vec2 q, vec2 c, vec2 b, float r) {
vec2 e = abs(q - c) - b + vec2(r);
return length(max(e, 0.0)) + min(max(e.x, e.y), 0.0) - r;
}
float shape(vec2 q, float k, float a) {
if (k < 1.5) return min(box(q, vec2(0.0, 0.64), vec2(0.48 * a, 0.27), 0.10), box(q, vec2(0.0, 0.30), vec2(0.33 * a, 0.17), 0.07));
if (k < 2.5) return min(box(q, vec2(0.0, 0.52), vec2(0.48 * a, 0.47), 0.04), box(q, vec2(0.0, 0.96), vec2(0.40 * a, 0.04), 0.02));
if (k < 3.5) return min(min(box(q, vec2(0.0, 0.46), vec2(0.12, 0.27), 0.09), length(q - vec2(0.0, 0.11)) - 0.09), box(q, vec2(0.0, 0.85), vec2(0.05, 0.15), 0.04));
float head = length(q - vec2(0.0, 0.08)) - 0.075;
float body = min(head, box(q, vec2(0.0, 0.34), vec2(0.13, 0.19), 0.07));
if (k < 4.5) return min(body, box(vec2(abs(q.x), q.y), vec2(0.06, 0.76), vec2(0.045, 0.23), 0.04));
if (k < 5.5) return min(body, abs(length(q - vec2(0.0, 0.79)) - 0.18) - 0.03);
return abs((abs(q.x) + abs(q.y - 0.5)) * 0.7071 - 0.3) - 0.035;
}
vec3 lampc(float k) {
return k < 1.5 ? vec3(0.820, 0.827, 0.850) : k < 2.5 ? vec3(0.683, 0.400, 0.271) : k < 3.5 ? vec3(0.577, 0.588, 0.518) : vec3(0.549, 0.573, 0.608);
}
void main() {
vec2 p = v_uv * u_size;
vec4 c = vec4(0.0);
vec3 ink = vec3(0.740, 0.750, 0.762);
for (int i = 0; i < 16; i++) {
vec4 b = u_ob[i];
vec4 m = u_oc[i];
vec4 o = vec4(0.0);
if (m.x > 6.5 && m.x < 10.5) {
float r = max(b.w, 1.0);
vec2 d0 = (p - b.xy) / r;
float hs = b.z / r;
if (abs(d0.x) < hs + 11.0 && abs(d0.y) < 11.0) {
float d = hs > 0.8 / r ? min(length(d0 - vec2(hs, 0.0)), length(d0 + vec2(hs, 0.0))) : length(d0);
float a = max(1.0 - smoothstep(1.0 - 0.7 / r, 1.0 + 0.7 / r, d), (1.0 - smoothstep(1.0, 3.0, d)) * 0.16);
float kr = m.w * (1.0 - smoothstep(0.3, 1.3, abs(length(d0) - max(max(hs + 3.0, 5.0), 9.0 / r)) * r)) * 0.85;
o = vec4(kr > a ? ink : lampc(m.x - 6.0), max(a, kr));
}
} else if (b.w > 1.0) {
float a = b.z / b.w;
float rq = 0.5 * max(a, 1.0) + 0.25;
float ex = m.w > 0.5 ? rq * b.w + 3.0 : 0.0;
if (abs(p.x - b.x) < max(0.6 * b.z + 3.0, ex) && p.y > min(b.y - b.w - 2.0, b.y - 0.5 * b.w - ex) && p.y < max(b.y + 0.12 * b.w + 2.0, b.y - 0.5 * b.w + ex)) {
vec2 q = vec2(p.x - b.x, p.y - (b.y - b.w)) / b.w;
float aa = 1.0 / b.w;
if (m.x < 10.5) {
vec2 s = (q - vec2(0.0, 1.0)) / vec2(0.5 * a + 0.08, 0.06);
float sh = (1.0 - smoothstep(0.3, 1.0, dot(s, s))) * 0.45;
float d = shape(q, m.x, a);
float k = 1.0 - smoothstep(-aa, aa, d);
vec3 col = u_fill * (0.78 + 0.22 * (1.0 - q.y)) * (0.72 + 0.28 * smoothstep(-0.06, -0.015, d));
o = mix(vec4(0.0, 0.0, 0.0, sh), vec4(col, 1.0), k);
if (m.z > 0.5) {
float lx = (m.x > 2.5 && m.x < 3.5) || (m.x > 4.5 && m.x < 5.5) ? 0.0 : 0.36 * a;
vec2 lq = vec2(abs(q.x) - lx, q.y - (m.x > 1.5 && m.x < 2.5 ? 0.80 : 0.58));
float dl = length(lq);
float la = max(1.0 - smoothstep(0.05, 0.05 + aa, dl), (1.0 - smoothstep(0.0, 0.22, dl)) * 0.35);
o = vec4(mix(o.rgb, lampc(m.z), la), max(o.a, la));
}
}
float kr = m.w * (1.0 - smoothstep(0.6 * aa, 1.6 * aa, abs(length(q - vec2(0.0, 0.5)) - rq))) * 0.85;
o = vec4(mix(o.rgb, ink, kr), max(o.a, kr));
}
}
o.a *= m.y;
if (o.a > 0.0) {
float na = o.a + c.a * (1.0 - o.a);
c = vec4((o.rgb * o.a + c.rgb * c.a * (1.0 - o.a)) / max(na, 0.001), na);
}
}
gl_FragColor = vec4(c.rgb * (1.0 - 0.65 * u_dim.x), c.a);
}
